var j = $input.first().json.body || $input.first().json;

function slug(s) {
  return String(s || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 80);
}

function numOrNull(v) {
  if (v == null || v === '') return null;
  var n = Number(v);
  return Number.isFinite(n) ? Math.round(n * 1000) / 1000 : null;
}

var address = String(j.address || '').trim();
var apartment = String(j.apartment || '').trim();
var typedCold = numOrNull(j.cold_water);
var typedHot = numOrNull(j.hot_water);

return [{
  json: {
    address: address,
    apartment: apartment,
    cold_water: typedCold,
    hot_water: typedHot,
    typed_cold: typedCold,
    typed_hot: typedHot,
    cold_photo: j.cold_photo || null,
    hot_photo: j.hot_photo || null,
    timestamp: j.timestamp || new Date().toISOString(),
    lookup_key: 'wm:' + slug(address) + ':' + slug(apartment),
    address_slug: slug(address),
    year_month: (function () {
      var d = new Date();
      var m = d.getMonth() + 1;
      return d.getFullYear() + '-' + (m < 10 ? '0' : '') + m;
    })(),
    reading_warnings: []
  }
}];

var row = $input.first().json;

var prompt =
  'This is a photo of a water meter display. ' +
  'Return ONLY a JSON object with one key "reading_m3": the total meter reading in cubic metres as a number (use a dot for decimals, max 3 decimal places). ' +
  'If unreadable, return {"reading_m3":null}. No other text.';

function buildBody(base64, label) {
  if (!base64 || String(base64).trim() === '') return null;
  return {
    model: 'gpt-4o-mini',
    temperature: 0,
    max_tokens: 80,
    messages: [
      {
        role: 'user',
        content: [
          { type: 'text', text: prompt + ' (' + label + ')' },
          {
            type: 'image_url',
            image_url: { url: 'data:image/jpeg;base64,' + String(base64).trim() }
          }
        ]
      }
    ]
  };
}

return [
  {
    json: Object.assign({}, row, {
      cold_openai_request: buildBody(row.cold_photo, 'cold water'),
      hot_openai_request: buildBody(row.hot_photo, 'hot water')
    })
  }
];

var row = $('Build OCR bodies').first().json;
var warnings = Array.isArray(row.reading_warnings) ? row.reading_warnings.slice() : [];

function parseReadingText(text) {
  if (!text) return null;
  var m = String(text).replace(/\s+/g, ' ').match(/\d+[.,]?\d*/);
  if (!m) return null;
  var n = Number(m[0].replace(',', '.'));
  if (!Number.isFinite(n) || n < 0) return null;
  return Math.round(n * 1000) / 1000;
}

function readingsDiffer(a, b) {
  if (a == null || b == null) return false;
  return Math.abs(Number(a) - Number(b)) > 0.001;
}

function parseOpenAiNode(nodeName) {
  try {
    var res = $(nodeName).first().json;
    var content = res && res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
    if (!content) return null;
    try {
      var jsonMatch = String(content).match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        var parsed = JSON.parse(jsonMatch[0]);
        if (parsed.reading_m3 != null) return parseReadingText(String(parsed.reading_m3));
      }
    } catch (e1) {}
    return parseReadingText(content);
  } catch (e2) {
    return null;
  }
}

function openAiError(nodeName) {
  try {
    var res = $(nodeName).first().json;
    if (res && res.error) return String(res.error.message || res.error);
  } catch (e) {}
  return null;
}

var ocrCold = row.cold_openai_request ? parseOpenAiNode('OCR cold OpenAI') : null;
var ocrHot = row.hot_openai_request ? parseOpenAiNode('OCR hot OpenAI') : null;
var ocrError = openAiError('OCR cold OpenAI') || openAiError('OCR hot OpenAI') || null;

var cold = row.typed_cold;
var hot = row.typed_hot;

if (row.typed_cold == null && ocrCold != null) {
  cold = ocrCold;
} else if (row.typed_cold != null && ocrCold != null && readingsDiffer(row.typed_cold, ocrCold)) {
  warnings.push(
    'Külmavee foto näitas teist näitu (foto: ' +
      ocrCold +
      ' m³, sisestatud: ' +
      row.typed_cold +
      ' m³). Salvestasime sisestatud väärtuse.'
  );
}

if (row.typed_hot == null && ocrHot != null) {
  hot = ocrHot;
} else if (row.typed_hot != null && ocrHot != null && readingsDiffer(row.typed_hot, ocrHot)) {
  warnings.push(
    'Soe vee foto näitas teist näitu (foto: ' +
      ocrHot +
      ' m³, sisestatud: ' +
      row.typed_hot +
      ' m³). Salvestasime sisestatud väärtuse.'
  );
}

var hadPhoto = Boolean(row.cold_photo || row.hot_photo);
if (hadPhoto && cold == null && hot == null) {
  if (ocrError) {
    warnings.push('Fotolt näitu ei õnnestunud tuvastada (OpenAI: ' + ocrError + ').');
  } else {
    warnings.push('Fotolt näitu ei õnnestunud tuvastada. Sisestage näit käsitsi või tehke selgem foto.');
  }
}

return [
  {
    json: Object.assign({}, row, {
      cold_water: cold,
      hot_water: hot,
      ocr_cold: ocrCold,
      ocr_hot: ocrHot,
      ocr_error: ocrError,
      reading_warnings: warnings
    })
  }
];

var row = $input.first().json;
var reg = row.registry;
if (typeof reg === 'string') {
  try { reg = JSON.parse(reg); } catch (e) { reg = null; }
}
if (!reg || !reg.cold_meter_id) {
  return [{
    json: Object.assign({}, row, {
      found: false,
      validation_ok: false,
      response_status: 'error',
      response_message: 'Address or apartment not serviced by this company.'
    })
  }];
}

var cold = row.cold_water == null ? null : Number(row.cold_water);
var hot = row.hot_water == null ? null : Number(row.hot_water);
var warnings = Array.isArray(row.reading_warnings) ? row.reading_warnings : [];

if (cold == null && hot == null) {
  return [{
    json: Object.assign({}, row, {
      found: true,
      registry: reg,
      validation_ok: false,
      response_status: 'error',
      response_message: 'Sisestage vähemalt ühe arvesti näit või lisage loetav foto.'
    })
  }];
}

if (cold != null && !isNaN(cold) && cold < Number(reg.cold_last_reading)) {
  return [{
    json: Object.assign({}, row, {
      found: true,
      registry: reg,
      validation_ok: false,
      response_status: 'error',
      response_message:
        'Cold water reading cannot be lower than the previous reading. Please check and try again.'
    })
  }];
}
if (hot != null && !isNaN(hot) && hot < Number(reg.hot_last_reading)) {
  return [{
    json: Object.assign({}, row, {
      found: true,
      registry: reg,
      validation_ok: false,
      response_status: 'error',
      response_message:
        'Hot water reading cannot be lower than the previous reading. Please check and try again.'
    })
  }];
}

var okMsg = 'Andmed on edukalt töödeldud.';
if (warnings.length) okMsg += ' ' + warnings.join(' ');

return [{
  json: Object.assign({}, row, {
    found: true,
    registry: reg,
    validation_ok: true,
    response_status: 'success',
    response_message: okMsg,
    reading_warnings: warnings
  })
}];

var row = $input.first().json;
var r = row.registry;
var items = [];
var t = row.timestamp;

if (row.cold_water != null && !isNaN(Number(row.cold_water))) {
  items.push({
    meter_id: String(r.cold_meter_id),
    client_id: String(r.client_id),
    value: Number(row.cold_water),
    value_type: 'reading',
    time: t
  });
}
if (row.hot_water != null && !isNaN(Number(row.hot_water))) {
  items.push({
    meter_id: String(r.hot_meter_id),
    client_id: String(r.client_id),
    value: Number(row.hot_water),
    value_type: 'reading',
    time: t
  });
}

var apt = String(row.apartment || '').replace(/[^a-zA-Z0-9]/g, '');
return [{
  json: Object.assign({}, row, {
    korto_body: items,
    ftp_cold_name: row.year_month + '_' + row.address_slug + '_' + apt + '_cold.jpg',
    ftp_hot_name: row.year_month + '_' + row.address_slug + '_' + apt + '_hot.jpg',
    ftp_dir: '/water-meters/' + row.year_month
  })
}];

var src = $('Build Korto + FTP names').first().json;
var res = $input.first().json;
var err = res && res.error;
var kortoOk = !err;
var errMsg = '';

if (err) {
  errMsg = String(err.message || err);
  try {
    var m = errMsg.match(/\{[\s\S]*\}/);
    if (m) {
      var body = m[0].replace(/\\\"/g, '"');
      var parsed = JSON.parse(body);
      if (parsed.errors && parsed.errors.length) {
        errMsg = parsed.errors.map(String).join('; ');
      }
    }
  } catch (e1) {}
}

return [{
  json: Object.assign({}, src, {
    korto_ok: kortoOk,
    korto_error: kortoOk ? null : errMsg,
    korto_response: kortoOk ? res : null
  })
}];

var row = $input.first().json;
var alertEmail = 'Aleksandr@arhangelski.com';
var errMsg = String(row.korto_error || 'Korto API push failed.');
var userMsg = 'Andmeid ei õnnestunud salvestada. Palun proovige hiljem uuesti.';

var lines = [
  'Veearvestite vorm — Korto API viga',
  '',
  'Viga: ' + errMsg,
  'Aadress: ' + String(row.address || ''),
  'Korter: ' + String(row.apartment || ''),
  'Redis võti: ' + String(row.lookup_key || ''),
  'Külm vesi (m³): ' + (row.cold_water != null ? row.cold_water : '-'),
  'Soe vesi (m³): ' + (row.hot_water != null ? row.hot_water : '-'),
  'Elaniku e-post: ' + (row.registry && row.registry.resident_email ? row.registry.resident_email : '-'),
  'Aeg: ' + String(row.timestamp || '')
];

return [{
  json: Object.assign({}, row, {
    wm_alert_email: alertEmail,
    smtp_error_subject:
      '[Compath WM] Korto API viga — ' + String(row.address || '').slice(0, 60),
    smtp_error_text: lines.join('\n'),
    response_message: userMsg,
    response_status: 'error'
  })
}];

var row = $input.first().json;
if (!row.wm_alert_email) {
  row = $('Prepare error notify').first().json;
}

var item = { json: row, binary: {} };

var apt = String(row.apartment || '').replace(/[^a-zA-Z0-9]/g, '') || 'na';
var slug = String(row.address_slug || 'address').slice(0, 80);
var ts = String(row.timestamp || '').replace(/[:.]/g, '-').slice(0, 19);
var stem = slug + '_apt' + apt + '_' + ts;

function attach(key, base64, label) {
  if (!base64 || String(base64).trim() === '') return;
  item.binary[key] = {
    data: String(base64).trim(),
    mimeType: 'image/jpeg',
    fileExtension: 'jpg',
    fileName: stem + '_' + label + '.jpg'
  };
}

attach('cold_attachment', row.cold_photo, 'cold');
attach('hot_attachment', row.hot_photo, 'hot');

return [item];

function randomToken() {
  var chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  var out = '';
  for (var i = 0; i < 32; i++) {
    out += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return out;
}

var row = $input.first().json;

var isUnknown = row.found !== true;
var errMsg = String(row.response_message || 'Request failed.');
var apt = String(row.apartment || '').replace(/[^a-zA-Z0-9]/g, '') || 'na';
var slug = String(row.address_slug || 'address').slice(0, 80);
var ts = String(row.timestamp || new Date().toISOString()).replace(/[:.]/g, '-').slice(0, 19);
var fileStem = slug + '_apt' + apt + '_' + ts;
var alertEmail = String(row.wm_alert_email || 'Aleksandr@arhangelski.com').trim() || 'Aleksandr@arhangelski.com';

var lines = [
  'Veearvestite vorm — viga',
  '',
  'Veateade (kasutajale näidatud): ' + errMsg,
  'Aadress: ' + String(row.address || ''),
  'Korter: ' + String(row.apartment || ''),
  'Redis võti: ' + String(row.lookup_key || ''),
  'Külm vesi (m³): ' + (row.cold_water != null ? row.cold_water : '-'),
  'Soe vesi (m³): ' + (row.hot_water != null ? row.hot_water : '-'),
  'OCR külm: ' + (row.ocr_cold != null ? row.ocr_cold : '-'),
  'OCR soe: ' + (row.ocr_hot != null ? row.ocr_hot : '-'),
  'Aeg: ' + String(row.timestamp || ''),
  'Tüüp: ' + (isUnknown ? 'registreerimata klient' : 'valideerimise viga')
];

var confirmToken = null;
var confirmUrl = null;
var pendingRedisKey = null;
var pendingRedisValue = null;

if (isUnknown) {
  confirmToken = randomToken();
  pendingRedisKey = 'wm:pending:' + confirmToken;
  pendingRedisValue = JSON.stringify({
    lookup_key: String(row.lookup_key || ''),
    address: String(row.address || ''),
    apartment: String(row.apartment || ''),
    cold_water: row.cold_water != null ? Number(row.cold_water) : null,
    hot_water: row.hot_water != null ? Number(row.hot_water) : null,
    timestamp: String(row.timestamp || ''),
    created_at: new Date().toISOString()
  });
  confirmUrl =
    'https://n8n.dbtmuuga.ee/form/wm-register-address?token=' + encodeURIComponent(confirmToken);
  lines.push('');
  lines.push('Registreeri aadress Redis registrisse (kinnituse vorm n8n-is):');
  lines.push(confirmUrl);
}

return [{
  json: Object.assign({}, row, {
    wm_alert_email: alertEmail,
    error_unknown_customer: isUnknown,
    confirm_token: confirmToken,
    confirm_url: confirmUrl,
    pending_redis_key: pendingRedisKey,
    pending_redis_value: pendingRedisValue,
    ftp_unknown_dir: '/unknown customers',
    ftp_unknown_cold_path: isUnknown && row.cold_photo
      ? '/unknown customers/' + fileStem + '_cold.jpg'
      : null,
    ftp_unknown_hot_path: isUnknown && row.hot_photo
      ? '/unknown customers/' + fileStem + '_hot.jpg'
      : null,
    smtp_error_subject:
      (isUnknown ? '[Compath WM] Registreerimata aadress' : '[Compath WM] Valideerimise viga') +
      ' — ' +
      String(row.address || '').slice(0, 60),
    smtp_error_text: lines.join('\n')
  })
}];
